	for ; j < len(toks); j++ {
		if toks[j].kind != 'o' {
			continue
		}
		switch toks[j].text {
		case "(", "[":
			d++
		case ")", "]":
			if d--; d == 0 {
				return j + 1
			}
		}
	}
	return j
